def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); comp=[]
          while stack:
            y,x=stack.pop(); comp.append((y,x))
            for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
              if 0<=yy<h and 0<=xx<w and grid[yy][xx] and (yy,xx) not in seen:
                seen.add((yy,xx)); stack.append((yy,xx))
          comps.append(comp)
    return comps
